import {roadRoute} from './road-routes.js?v=life17';
import * as T from './three.module.js';import {FARMS,REGIONAL_BOUNDS} from './regional-farms.js?v=life17';import {namibiaTime,residentActivity} from './namibia-time.js?v=life17';import {hashSeed,circleClear,giveGoal,updateAgent} from './resident-ai.js?v=life17';import {onRoad} from './road-layout.js?v=life17';import {worldPath} from './world-path.js?v=county11';import {createFarmVehicle} from './vehicle-models.js?v=life17';
export const ERRAND_STOPS={shop:{name:'Village co-op',road:{x:-84,z:28},park:{x:-83,z:23},door:{x:-80,z:22}},mill:{name:'County Feed Mill',road:{x:64,z:37},park:{x:70.5,z:37},door:{x:72,z:32}}};
const cache=new Map();export function errandRoadRoute(p,destination){const key=p.id+destination;if(!cache.has(key))cache.set(key,roadRoute(p.approach,ERRAND_STOPS[destination].road));return cache.get(key).map(p=>({...p}));}
export function installResidentTrips({scene,world,state,blocked,mobile=false}){const cars=Array.from({length:mobile?1:2},(_,i)=>{const actor=createFarmVehicle('pickup',['#7f9399','#a58b6c'][i]);actor.root.name='Neighbour errand vehicle';actor.root.visible=false;scene.add(actor.root);actor.ready.then(()=>actor.root.traverse(o=>{if(o.isMesh)o.castShadow=false;}));const head=new T.Mesh(new T.SphereGeometry(.13,10,8),new T.MeshStandardMaterial({color:'#b98e6d'}));head.position.set(-.4,1.35,.65);actor.root.add(head);return {actor,trip:null};});let check=0,local=namibiaTime();
 function walkTo(t,goal){t.walkGoal=goal;t.r.agent.bounds=REGIONAL_BOUNDS;t.r.agent.route=[];return giveGoal(t.r.agent,goal,blocked);}
 function finish(t,c){const r=t.r;r.travel=null;r.inCar=false;r.agent.bounds=t.bounds;r.agent.route=[];r.agent.wait=2;r.activity='home';t.parent.add(r.root);r.root.position.set(r.agent.x,.2,r.agent.z);c.actor.root.visible=false;c.trip=null;}
 return {cars,tick(dt,player,focus=player,now=Date.now()){check+=dt;if(check>2){check=0;local=namibiaTime(now);for(const p of FARMS){const v=world.farms.get(p.id),r=v?.people?.residents[0];if(!r||r.travel||residentActivity(r.role,p.id+'-'+r.name,local)!=='errand')continue;const offset=hashSeed(p.id)%12,slot=local.date+':'+Math.floor((local.hour*60+local.minute+offset)/12);if(r.lastTripSlot===slot)continue;const c=cars.find(c=>!c.trip);if(!c)break;const destination=(hashSeed(p.id)+local.hour)%2?'mill':'shop',route=errandRoadRoute(p,destination);if(!route.length)continue;r.lastTripSlot=slot;const t={p,r,destination,stop:ERRAND_STOPS[destination],bounds:r.agent.bounds,parent:r.root.parent,stage:'boarding',x:p.x,z:p.z+25,heading:0,route:[],service:0};c.trip=t;r.travel=t;r.inCar=false;scene.add(r.root);r.root.visible=true;c.actor.root.position.set(t.x,.2,t.z);c.actor.root.visible=true;walkTo(t,{x:p.x+1.7,z:p.z+25});}}
 for(const c of cars){const t=c.trip;if(!t)continue;const r=t.r,near=Math.hypot(t.x-focus.x,t.z-focus.z)<(mobile?130:200);c.actor.root.visible=near;const distance=Math.hypot(r.agent.x-focus.x,r.agent.z-focus.z);if(distance<100&&!r.rig)world.farms.get(t.p.id).people.loadModels([r.name]);
 if(['boarding','walking','returning'].includes(t.stage)){const m=updateAgent(r.agent,dt,blocked,[{x:player.x,z:player.z,radius:.45}]);r.root.visible=distance<100;r.root.position.set(r.agent.x,.2,r.agent.z);r.root.rotation.y=r.agent.heading;r.rig?.update(dt,m.moved/dt);if(!r.agent.route.length){if(Math.hypot(r.agent.x-t.walkGoal.x,r.agent.z-t.walkGoal.z)>1.3){walkTo(t,t.walkGoal);continue;}if(t.stage==='walking'){t.stage='service';t.service=10+hashSeed(t.p.id)%12;}else {r.inCar=true;r.root.visible=false;t.stage=t.stage==='boarding'?'outbound':'homebound';const road=errandRoadRoute(t.p,t.destination);t.route=t.stage==='outbound'?[t.p.approach,...road,t.stop.park]:[t.stop.road,...road.reverse(),t.p.approach,{x:t.p.x,z:t.p.z+25}];}}}
 else if(t.stage==='service'){t.service-=dt;r.rig?.update(dt,0,'feed');if(t.service<=0){t.stage='returning';walkTo(t,{x:t.stop.park.x+1.8,z:t.stop.park.z});}}
 else {r.root.visible=false;const target=t.route[0];if(!target){if(t.stage==='outbound'){t.stage='walking';r.inCar=false;r.agent.x=t.x+1.8;r.agent.z=t.z;walkTo(t,t.stop.door);}else {r.agent.x=t.x+1.8;r.agent.z=t.z;finish(t,c);}continue;}const dx=target.x-t.x,dz=target.z-t.z,d=Math.hypot(dx,dz);if(d<.35){t.route.shift();continue;}const want=Math.atan2(dx,dz),turn=Math.atan2(Math.sin(want-t.heading),Math.cos(want-t.heading));t.heading+=Math.max(-dt*2.5,Math.min(dt*2.5,turn));const obstacles=[{x:player.x,z:player.z},...Object.values(state.vehicles.owned),...cars.filter(o=>o!==c&&o.trip).map(o=>o.trip)],ahead={x:t.x+dx/d*3,z:t.z+dz/d*3},stop=obstacles.some(o=>Math.hypot(ahead.x-o.x,ahead.z-o.z)<2.3);const step=stop||Math.abs(turn)>1?0:Math.min(d,dt*6);t.x+=dx/d*step;t.z+=dz/d*step;c.actor.root.position.set(t.x,.2,t.z);c.actor.root.rotation.y=t.heading;c.actor.update(step,Math.max(-1,Math.min(1,-turn)));}
 }
 }};
}
